D = []  # домены
def dom(code, name, desc): d={'code':code,'name':name,'desc':desc,'tables':[]}; D.append(d); return d
def T(d, name, desc, cols, extra=None, rows=None):
    d['tables'].append({'name':name,'desc':desc,'cols':cols,'extra':extra or [],'rows':rows})

