# связи: (from_table, to_table, card, label) выводим из FK
def rels():
    R=[]
    for d in D:
        for tb in d['tables']:
            for (n,ty,k,_) in tb['cols']:
                for part in k.split():
                    if part.startswith('FK>'):
                        R.append((tb['name'],part[3:],n,'NN' in k.split() or 'PK' in k.split()))
    return R
TBL={tb['name']:(d['code'],tb) for d in D for tb in d['tables']}
